/// <summary>
/// AVA/WEN/2025/04/07        AVA_012999_EntAsset_Project
/// </summary>
/// <param name = "_workOrderType">EntAssetWorkOrderTypeRecID</param>
/// <param name = "_objectType">EntAssetObjectTypeRecID</param>
/// <param name = "_object">EntAssetObjectRecID</param>
/// <param name = "_projId">projId</param>
/// <param name = "_date">TransDate</param>
/// <returns>boolean</returns>
public static boolean exist(EntAssetWorkOrderTypeRecID	  _workOrderType,
                        EntAssetObjectTypeRecID          _objectType,
                        EntAssetObjectRecID              _object,
                        projId                           _projId, 
                        TransDate                        _date)
{
    EntAssetWorkOrderParentProject		parentProject;

    select firstonly validTimeState(_date, _date) parentProject
        where parentProject.WorkOrderType      == _workorderType &&
                parentProject.ObjectType         == _objectType &&
                parentProject.Object             == _object &&
                parentProject.ProjId              == _projId;

    return parentProject.RecId;
}
